// TypeScript Version: 4.1

/**
* Computes the forward real-valued fast Fourier transform (FFT).
*
* @param N - length of the sequence to transform
* @param r - input/output array containing the sequence to transform
* @param strideR - stride length for `r`
* @param offsetR - starting index for `r`
* @param workspace - workspace array containing pre-computed values
* @param strideW - stride length for `workspace`
* @param offsetW - starting index for `workspace`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
*
* var N = 4;
*
* var workspace = new Float64Array( ( 2*N ) + 34 );
* rffti( N, workspace, 1, 0 );
*
* var r = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* rfftf( N, r, 1, 0, workspace, 1, 0 );
* // r => <Float64Array>[ 10.0, -2.0, 2.0, -2.0 ]
*/
declare function rfftf( N: number, r: Float64Array, strideR: number, offsetR: number, workspace: Float64Array, strideW: number, offsetW: number ): void;


// EXPORTS //

export = rfftf;
